"""Render the fixed-seed attribution study from its machine-readable artifact."""
import json
from pathlib import Path

artifact = json.loads(Path('reports/attribution.json').read_text())

def pct(value):
    return 'n/a' if value is None else f'{value * 100:.2f}%'

def metric(record, key):
    ci = record.get('ci95', {}).get(key)
    return pct(record[key]) + (f' [{pct(ci[0])}, {pct(ci[1])}]' if ci else '')

cells = artifact['cells']
lines = [
    '<!-- Generated by scripts/render_attribution.py from reports/attribution.json. -->',
    '# Attribution of the V2 false-positive-rate change',
    '',
    'This fixed-seed factorial study separates the legacy generator/detector from '
    'the current generator/detector. It uses Seed A 31001 for calibration and Seed '
    'B 31002 for evaluation in every cell. It measures synthetic scenario recovery, '
    'not real-world fraud performance.',
    '',
    '## Selected-on-A result per cell',
    '',
    '| Generator | Detector | A-selected threshold | Recall [95% CI] | FPR [95% CI] | Precision [95% CI] | Evasive recall [95% CI] |',
    '|---|---|---:|---|---|---|---|',
]
for key, label in [
    ('old_generator_old_detector', ('legacy', 'legacy')),
    ('old_generator_new_detector', ('legacy', 'current')),
    ('new_generator_old_detector', ('current', 'legacy')),
    ('new_generator_new_detector', ('current', 'current')),
]:
    cell = cells[key]
    monthly = cell['selected']['factory_month']
    evasive = cell['selected']['evasive_recall']
    lines.append(f'| {label[0]} | {label[1]} | {cell["selected_threshold"]:.3f} | {metric(monthly,"recall")} | {metric(monthly,"fpr")} | {metric(monthly,"precision")} | {metric(evasive,"recall")} |')

lines += [
    '', '## Fixed-threshold decomposition', '',
    '| Generator | Detector | Fixed threshold | Recall | FPR | Precision | Evasive recall |',
    '|---|---|---:|---:|---:|---:|---:|',
]
for key, label in [
    ('old_generator_old_detector', ('legacy', 'legacy')),
    ('new_generator_old_detector', ('current', 'legacy')),
]:
    for result_key, threshold in [('fixed_2_5pct', '.025'), ('fixed_5pct', '.050')]:
        m = cells[key][result_key]['factory_month']
        e = cells[key][result_key]['evasive_recall']
        lines.append(f'| {label[0]} | {label[1]} | {threshold} | {pct(m["recall"])} | {pct(m["fpr"])} | {pct(m["precision"])} | {pct(e["recall"])} |')

lines += [
    '', '## Decoy FPR at each A-selected threshold', '',
    '| Decoy | Legacy generator + detector | Current generator + detector |',
    '|---|---:|---:|',
]
old = cells['old_generator_old_detector']['selected']['per_decoy_fpr']
new = cells['new_generator_new_detector']['selected']['per_decoy_fpr']
for scenario in sorted(old):
    lines.append(f'| {scenario.replace("_", " ")} | {metric(old[scenario],"fpr")} | {metric(new[scenario],"fpr")} |')

lines += [
    '', '## Conclusion', '',
    'The FPR decrease from 16.65% to 2.22% is caused by the A-selected threshold '
    'moving from 2.5% to 5.0%. At a fixed threshold, legacy and current detector SQL '
    'produce the same decision metrics; ranking cannot affect FPR because it orders '
    'only already-prioritised cases. The new generator stock mechanics do not change '
    'FPR at either fixed threshold, but at 5.0% they raise recall from 65.81% to '
    '82.74% and evasive recall from 6.95% to 57.24%. This is a planted-mechanic '
    'benefit, not evidence of real-world generalisation.',
    '',
    'The current detector therefore has a more selective operating point, with a '
    'material cost: evasive recall remains only 57.24% on V2-B and 49.14% on V2-C. '
    'Those misses remain a headline limitation.',
]
Path('docs/ATTRIBUTION.md').write_text('\n'.join(lines) + '\n')
